use crate::{
    SyntaxKind::{self, *},
    view::{AstNode, Node},
};

use nodes::{ExprStmt, Item, LetStmt, Stmt};

// Stmt is the only nested enum, so it's easier to just hand-write it
impl<'t> AstNode<'t> for Stmt<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        match kind {
            LET_STMT | EXPR_STMT => true,
            _ => Item::can_cast(kind),
        }
    }

    fn cast(syntax: Node<'t>) -> Option<Self> {
        let res = match syntax.kind() {
            LET_STMT => Stmt::LetStmt(LetStmt { syntax }),
            EXPR_STMT => Stmt::ExprStmt(ExprStmt { syntax }),
            _ => Stmt::Item(Item::cast(syntax)?),
        };
        Some(res)
    }

    fn syntax(&self) -> Node<'t> {
        match self {
            Stmt::LetStmt(it) => it.syntax,
            Stmt::ExprStmt(it) => it.syntax,
            Stmt::Item(it) => it.syntax(),
        }
    }
}
